<?php
require_once 'includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$role=$_POST['role']??'employee';if($name===''||$username===''||strlen($password)<8||!in_array($role,['admin','employee'],true)){flash('Enter valid details. Password must be at least 8 characters.','error');}else{try{$q=db()->prepare('INSERT INTO users(name,username,password,role) VALUES(?,?,?,?)');$q->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('User created.');}catch(PDOException $e){flash('Username already exists.','error');}}redirect('users.php');}$users=db()->query('SELECT id,name,username,role,created_at FROM users ORDER BY id')->fetchAll();$page_title='Users';require 'includes/header.php'; ?>
<div class="panel"><h1>User Management</h1><div class="table-wrap"><table><tr><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr><?php foreach($users as $u): ?><tr><td><?= e($u['name']) ?></td><td><?= e($u['username']) ?></td><td><?= e($u['role']) ?></td><td><?= e($u['created_at']) ?></td></tr><?php endforeach; ?></table></div></div><div class="panel"><h2>Create user</h2><form method="post" class="form-grid"><?= csrf_field() ?><label>Full name<input name="name" required></label><label>Username<input name="username" required></label><label>Password (min 8 characters)<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option value="employee">Employee</option><option value="admin">Administrator</option></select></label><div><button class="button">Create user</button></div></form></div>
<?php require 'includes/footer.php'; ?>
